pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // Restrict amounts to avoid overflow and keep within reasonable bounds
        bound(depositAmount, 0, type(uint128).max);
        bound(withdrawAmount, 0, type(uint128).max);

        // Fund the contract with the owner's own Ether
        address owner = c.owner();
        vm.deal(owner, depositAmount + withdrawAmount);
        vm.prank(owner);
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent, "deposit failed");

        // Alternatively, also withdraw a partial amount to ensure balance changes are independent
        if (withdrawAmount > 0 && withdrawAmount <= address(c).balance) {
            vm.prank(owner);
            c.withdraw(withdrawAmount);
        }

        // Record owner's balance before withdrawAll
        uint256 ownerBalanceBefore = owner.balance;
        uint256 contractBalanceBefore = address(c).balance;

        // Now call withdrawAll
        vm.prank(owner);
        c.withdrawAll();

        // The owner's balance should increase by exactly the contract's prior balance
        assertTrue(owner.balance == ownerBalanceBefore + contractBalanceBefore);
    }
}

