contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 withdrawalAmount) public {
        // Deal some Ether to the contract so it has something to withdraw
        vm.deal(address(c), 100 ether);
        // Bound the withdrawal amount to at most the contract's balance to keep the call admissible
        withdrawalAmount = bound(withdrawalAmount, 1, address(c).balance);
        uint256 balanceBefore = address(c).balance;
        // Owner calls withdraw
        vm.prank(address(0x1));
        // The original owner is msg.sender of deployment, but owner is private? Actually 'owner' is public.
        // We need to ensure msg.sender is the owner. Set up owner properly.
        // The contract C sets owner = payable(msg.sender) in declaration, so deployer (this test) is owner.
        // We can prank to this test's address or simply call as the test itself; but the test is already the owner.
        // Use a valid call: prank as the owner address (address(this)).
        vm.prank(address(this));
        c.withdraw(withdrawalAmount);
        uint256 balanceAfter = address(c).balance;
        // General rule: the balance must decrease by exactly the withdrawn amount
        assertTrue(balanceAfter == balanceBefore - withdrawalAmount);
    }
}

